        if isinstance(v, dict):
            for x in v.values():
                if isinstance(x, (list, tuple, dict)):
                    r += pts(x)
        elif isinstance(v, (list, tuple)):
            for x in v:
                if isinstance(x, (list, tuple, dict)):
                    r += pts(x)
        return r

